import React from 'react';
import { Mountain, Shield, Brain, Database, TrendingUp, Zap } from 'lucide-react';

const Navbar = ({ activeTab, setActiveTab }) => {
  const tabs = [
    { name: 'Command Center', icon: Shield },
    { name: 'Data Ingestion', icon: Database },
    { name: 'Model Training', icon: Brain },
    { name: 'Simulation', icon: TrendingUp }
  ];
  
  const statusIndicators = [
    { name: 'DEM Model', status: 'online' },
    { name: 'CNN Model', status: 'online' },
    { name: 'Weather API', status: 'connected' },
    { name: 'Seismic Monitor', status: 'online' }
  ];

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 bg-gradient-to-r from-gray-900 via-gray-800 to-gray-900 border-b border-orange-500/30 shadow-2xl h-16">
      <div className="px-4 py-3 h-full">
        <div className="flex items-center justify-between h-full">
          {/* Logo and Title */}
          <div className="flex items-center space-x-3">
            <div className="relative">
              <div className="bg-gradient-to-br from-orange-500 to-red-600 p-2 rounded-lg shadow-lg">
                <Mountain className="w-6 h-6 text-white" />
              </div>
              <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full animate-pulse"></div>
            </div>
            <div>
              <h1 className="text-lg font-bold bg-gradient-to-r from-orange-400 to-red-500 bg-clip-text text-transparent">
                AI-Powered Rockfall Prediction Command Center
              </h1>
              <p className="text-xs text-gray-400 flex items-center mt-1">
                <Zap className="w-3 h-3 mr-1 text-yellow-500" />
                Real-time Geological Risk Assessment & Management
              </p>
            </div>
          </div>

          {/* Navigation Tabs */}
          <div className="flex space-x-1">
            {tabs.map((tab) => (
              <button
                key={tab.name}
                onClick={() => setActiveTab(tab.name)}
                className={`flex items-center space-x-2 px-3 py-2 rounded-lg text-xs font-medium transition-all duration-300 ${
                  activeTab === tab.name
                    ? 'bg-gradient-to-r from-orange-500 to-red-500 text-white shadow-lg scale-105'
                    : 'text-gray-300 hover:bg-gray-700/50 hover:text-orange-300'
                }`}
              >
                <tab.icon className="w-3 h-3" />
                <span>{tab.name}</span>
              </button>
            ))}
          </div>

          {/* Status Indicators */}
          <div className="flex items-center space-x-4">
            <div className="grid grid-cols-2 gap-2">
              {statusIndicators.map((indicator) => (
                <div key={indicator.name} className="flex items-center space-x-2 bg-gray-800/50 px-2 py-1 rounded-lg backdrop-blur-sm">
                  <div className="flex items-center space-x-1">
                    {indicator.status === 'online' || indicator.status === 'connected' ? (
                      <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                    ) : indicator.status === 'processing' ? (
                      <div className="w-2 h-2 bg-yellow-500 rounded-full animate-bounce"></div>
                    ) : (
                      <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></div>
                    )}
                    <span className="text-xs text-gray-300 font-medium">{indicator.name}</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="text-xs text-gray-400 bg-gray-800/30 px-2 py-1 rounded-lg backdrop-blur-sm">
              <div className="text-orange-400 font-mono">4:30:32 PM</div>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
